sp_theme.css_variables:
/* ==========================================================================
 * Enterprise Digital Portal — "EDP Sage" theme
 * ==========================================================================
 * Palette: muted, slightly grey-green SAGE accent + WARM neutrals (stone,
 * greige, warm off-white). The sage is reserved for accents, CTAs and focus
 * states; the warm neutrals carry every surface.
 *
 * STRUCTURE OF THIS FILE
 *   1. Service Portal / Bootstrap 3 SCSS variables  (structural starting
 *      point = OOTB Coral theme, re-pointed at the sage palette)
 *   2. Scale variables ($sp-space-*, $sp-text-*, $sp-icon-*) consumed by
 *      every widget / header / footer stylesheet in this app
 *   3. Runtime design tokens, declared TWICE:
 *        :root, [data-edp-theme="light"]  -> light palette
 *        [data-edp-theme="dark"]          -> dark palette
 *      Flipping the single `data-edp-theme` attribute on <html> re-themes the
 *      whole portal. The Theme Toggle widget does exactly that.
 *   4. Global surface / focus / motion rules (+ the no-footer layout guard)
 *   5. Catalog ordering shell (OOTB sc_cat_item) — verified selectors only
 *   6. Reduced-motion guard for sections 4-5
 *   7. OOTB Bootstrap + OOTB widget surfaces re-pointed at RUNTIME tokens
 *      <- this is the dark-mode fix; the root-cause note lives there
 *   8. Catalog journey: sc_landing / sc_category / sc_cat_item / search
 *   9. Explicit dark-scope hardening for OOTB hardcoded literals
 *  10. Reduced-motion guard for sections 7-8
 *
 * WHY TWO TOKEN SYSTEMS?
 *   --edp-*   : plain hex custom properties. ALL of this app's own CSS uses
 *               these, so the sage look and the runtime toggle are guaranteed.
 *   --now-*   : the UXF tokens that `sp-rgb()` resolves against. They are
 *               re-declared here (as "r, g, b" triplets, which is the format
 *               sp-rgb() expects) so the OOTB Bootstrap layer and OOTB widgets
 *               follow the same palette and flip with the same attribute.
 * ========================================================================== */


/* --------------------------------------------------------------------------
 * 1. SERVICE PORTAL / BOOTSTRAP 3 SCSS VARIABLES
 * Every variable ends with !default so downstream CSS can override.
 * All colours go through sp-rgb(<uxf-token>, <sage fallback>) — never raw hex.
 * -------------------------------------------------------------------------- */

// --- Warm neutral greys ---------------------------------------------------
$gray-base: #000000;
$gray-darker: sp-rgb(--now-color_text--primary, #1B1816) !default;
$gray-dark: sp-rgb(--now-color_text--primary, #2A2622) !default;
$gray: sp-rgb(--now-color_text--secondary, #443E39) !default;
$gray-light: sp-rgb(--now-color_text--tertiary, #635A52) !default;
$gray-lighter: sp-rgb(--now-color_background--secondary, #F7F3EF) !default;

// --- Brand ----------------------------------------------------------------
$brand-primary: sp-rgb(--now-color--primary-1, #6E8B6B) !default;
$brand-primary-light: sp-rgb(--now-color--interactive-1, #AEC2A7) !default;
$brand-primary-lighter: sp-rgb(--now-color--primary-0, #E4EBDF) !default;
$brand-primary-lightest: sp-rgb(--now-color--primary-0, #E4EBDF) !default;
$brand-primary-dark: sp-rgb(--now-color--primary-2, #4C6349) !default;
$brand-primary-darker: sp-rgb(--now-color--primary-3, #3A4C38) !default;
$primary: $brand-primary !default;

$brand-success: sp-rgb(--now-color_alert--positive-3, #2F6B4F) !default;
$brand-warning: sp-rgb(--now-color_alert--warning-3, #9A7418) !default;
$brand-danger: sp-rgb(--now-color_alert--critical-3, #B33A3A) !default;
$brand-info: sp-rgb(--now-color_alert--info-3, #2F6D8C) !default;
$success: $brand-success !default;
$warning: $brand-warning !default;
$danger: $brand-danger !default;
$info: $brand-info !default;

// --- Surfaces -------------------------------------------------------------
$background-primary: sp-rgb(--now-color_background--primary, #FFFCFA) !default;
$background-secondary: sp-rgb(--now-color_background--secondary, #F7F3EF) !default;
$background-tertiary: sp-rgb(--now-color_background--tertiary, #E2DAD2) !default;
$body-bg: $background-secondary !default;
$body-bg-tertiary: $background-tertiary !default;
$panel-bg: $background-primary !default;
$sp-page-bg: $background-secondary !default;
$sp-homepage-bg: $background-secondary !default;
$well-bg: $background-tertiary !default;
$component-active-bg: $background-secondary !default;
$table-bg: transparent !default;
$table-bg-accent: $background-secondary !default;
$table-bg-hover: $background-tertiary !default;

// --- Text -----------------------------------------------------------------
$text-primary: sp-rgb(--now-color_text--primary, #2A2622) !default;
$text-secondary: sp-rgb(--now-color_text--secondary, #443E39) !default;
$text-tertiary: sp-rgb(--now-color_text--tertiary, #635A52) !default;
$text-color: $text-primary !default;
$text-muted: $text-tertiary !default;
$input-color: $text-primary !default;
$sp-tagline-color: $text-primary !default;
$default-icon: $text-primary !default;
$primary-icon: $brand-primary-dark !default;

// --- Links ----------------------------------------------------------------
$link-color: sp-rgb(--now-color--link-2, #4C6349) !default;
$link-hover-color: sp-rgb(--now-color--link-3, #3A4C38) !default;
$link-hover-decoration: underline !default;

// --- Borders / dividers ---------------------------------------------------
$border-primary: sp-rgb(--now-color_border--primary, #A89C91) !default;
$border-secondary: sp-rgb(--now-color_border--secondary, #CFC5BB) !default;
$border-tertiary: sp-rgb(--now-color_border--tertiary, #E2DAD2) !default;
$panel-default-border: $border-tertiary !default;
$panel-inner-border: $border-tertiary !default;
$panel-border-color: $border-tertiary !default;
$table-border-color: $border-tertiary !default;
$nav-tabs-border-color: $border-tertiary !default;
$nav-tabs-justified-link-border-color: $border-tertiary !default;
$sp-b-border-color: $border-tertiary !default;

// --- Navbar (consumed by the EDP header CSS) ------------------------------
$navbar-inverse-bg: sp-rgb(--now-color_background--primary, #FFFCFA) !default;
$navbar-inverse-link-color: sp-rgb(--now-color_text--primary, #2A2622) !default;
$navbar-inverse-link-hover-color: sp-rgb(--now-color--primary-3, #3A4C38) !default;
$navbar-inverse-link-hover-bg: sp-rgb(--now-color--primary-0, #E4EBDF) !default;
$navbar-inverse-link-active-color: sp-rgb(--now-color--primary-3, #3A4C38) !default;
$navbar-inverse-link-active-bg: sp-rgb(--now-color--primary-0, #E4EBDF) !default;
$navbar-inverse-link-hover-border: sp-rgb(--now-color--primary-1, #6E8B6B) !default;
$sp-navbar-divider-color: sp-rgb(--now-color_divider--tertiary, #E2DAD2) !default;
$sp-navbar-bottom-width: 0.0625rem !default;
$sp-navbar-toggle-border-color: sp-rgb(--now-color_border--secondary, #CFC5BB) !default;

// --- Logo sizing (consumed by the EDP header CSS) -------------------------
$sp-logo-margin-x: 16px !default;
$sp-logo-margin-y: 8px !default;
$sp-logo-max-height: 36px !default;
$sp-logo-max-width: 200px !default;
$sp-logo-mobile-max-width: 150px !default;

// --- Buttons --------------------------------------------------------------
$btn-primary-color: sp-rgb(--now-color_text--primary-actionable, #FFFCFA) !default;
$btn-primary-bg: $brand-primary-dark !default;
$btn-primary-border: $brand-primary-dark !default;
$btn-default-color: $brand-primary-dark !default;
$btn-default-bg: $background-primary !default;
$btn-default-border: $border-secondary !default;
$btn-success-bg: $brand-success !default;
$btn-success-border: $brand-success !default;
$btn-success-color: $btn-primary-color !default;
$btn-clear-bg: transparent !default;
$btn-clear-text: $text-tertiary !default;
$btn-disabled-opacity: 0.4 !default;
$btn-interactive: sp-rgb(--now-color--interactive-2, #4C6349) !default;
$button-selected-color: $btn-primary-bg !default;
$login-btn-bg: $btn-primary-bg !default;
$login-btn-border: $btn-primary-border !default;
$login-mask-btn-bg: $background-primary !default;
$transparent-button-color: $brand-primary-dark !default;

// --- Form fields ----------------------------------------------------------
$input-border: sp-rgb(--now-color_border--primary, #A89C91) !default;
$input-border-focus: sp-rgb(--now-color--focus-ring, #556E52) !default;
$input-border-tab-focus: $input-border-focus !default;
$input-group-addon-bg: $background-secondary !default;
$sp-form-field--background-color: $background-primary !default;
$sp-form-field--background-color--readonly: $background-tertiary !default;
$sp-form-field-placeholder: $text-tertiary !default;
$panel-focus: sp-rgb(--now-color--focus-2, #556E52) !default;
$not-webkit-outline-color: $input-border-focus !default;
$webkit-outline-color: $input-border-focus !default;

// --- Panels ---------------------------------------------------------------
$panel-heading-background: $background-primary !default;
$panel-heading-color: $text-primary !default;
$panel-heading-icon-color: $text-primary !default;
$panel-default-heading-bg: $background-secondary !default;
$panel-default-text: $text-tertiary !default;
$panel-default-text-color: $text-primary !default;
$panel-primary-border: $brand-primary !default;
$panel-primary-heading-bg: $brand-primary-dark !default;
$panel-primary-text: sp-rgb(--now-color_text--primary-actionable, #FFFCFA) !default;
$panel-info-heading-bg: $brand-primary-lighter !default;
$panel-box-shadow: 0 0.25rem 0.75rem 0 rgba(68, 62, 57, 0.10) !default;
$panel-list-item: $brand-primary-lighter !default;
$list-group-hover-bg: $brand-primary-lighter !default;
$list-group-link-heading-color: $text-tertiary !default;

// --- Alerts / states ------------------------------------------------------
$state-success-bg: sp-rgb(--now-color_alert--positive-0, #D7E6DA) !default;
$state-success-border: $brand-success !default;
$state-success-text: $text-primary !default;
$state-warning-bg: sp-rgb(--now-color_alert--warning-0, #F2E9D2) !default;
$state-warning-border: $brand-warning !default;
$state-warning-text: $text-primary !default;
$state-danger-bg: sp-rgb(--now-color_alert--critical-0, #F6DEDE) !default;
$state-danger-border: $brand-danger !default;
$state-danger-text: $text-primary !default;
$state-info-bg: sp-rgb(--now-color_alert--info-0, #DCE7ED) !default;
$state-info-border: $brand-info !default;
$state-info-text: $text-primary !default;
$alert-success-bg: $state-success-bg !default;
$alert-success-border: $state-success-border !default;
$alert-success-text: $text-primary !default;
$alert-warning-bg: $state-warning-bg !default;
$alert-warning-border: $state-warning-border !default;
$alert-warning-text: $text-primary !default;
$alert-danger-bg: $state-danger-bg !default;
$alert-danger-border: $state-danger-border !default;
$alert-danger-text: $text-primary !default;
$alert-info-bg: $state-info-bg !default;
$alert-info-border: $state-info-border !default;
$alert-info-text: $text-primary !default;
$label-success-bg: $brand-success !default;
$label-info-bg: $brand-info !default;
$label-warning-bg: $brand-warning !default;
$label-danger-bg: $brand-danger !default;
$label-primary-bg: $brand-primary-dark !default;

// --- Dropdowns / modals / tooltips / popovers -----------------------------
$dropdown-bg: $background-primary !default;
$dropdown-border: $border-tertiary !default;
$dropdown-fallback-border: $border-tertiary !default;
$dropdown-divider-bg: $border-tertiary !default;
$dropdown-link-color: $text-primary !default;
$dropdown-link-hover-color: $brand-primary-darker !default;
$dropdown-link-hover-bg: $brand-primary-lighter !default;
$dropdown-link-active-bg: $brand-primary-dark !default;
$dropdown-link-active-color: $panel-primary-text !default;
$dropdown-link-disabled-color: $gray-light !default;
$modal-content-bg: $background-primary !default;
$modal-content-border-color: $border-tertiary !default;
$modal-content-fallback-border-color: $border-tertiary !default;
$modal-header-close-color: $text-primary !default;
$popover-bg: $background-primary !default;
$popover-border-color: $border-tertiary !default;
$popover-arrow-color: $background-primary !default;
$popover-arrow-outer-color: $border-tertiary !default;
$tooltip-bg: sp-rgb(--now-color_text--primary, #2A2622) !default;
$tooltip-color: sp-rgb(--now-color_background--primary, #FFFCFA) !default;
$tooltip-arrow-color: $tooltip-bg !default;
$tooltip-border-color: $tooltip-bg !default;

// --- Tabs -----------------------------------------------------------------
$sp-nav-tabs-color: $text-secondary !default;
$sp-nav-tabs-hover-color: $brand-primary-darker !default;
$sp-nav-tabs-active-tab: $brand-primary-dark !default;
$sp-nav-tabs-border-bottom-width: 2px !default;
$sp-nav-tabs-hover-bg: transparent !default;
$sp-nav-tabs-hover-font-weight: 600 !default;
$sp-nav-tabs-active-font-weight: 600 !default;
$sp-nav-tabs-focus-box-shadow: inset 0 0 0 2px $panel-focus !default;
$nav-tabs-link-hover-border-color: transparent !default;
$nav-tabs-active-link-hover-bg: transparent !default;
$nav-tabs-active-link-hover-color: $brand-primary-darker !default;
$nav-tabs-active-link-hover-border-color: $brand-primary-dark !default;

// --- Misc Service Portal hooks -------------------------------------------
$carousel-text-shadow: none !default;
$carousel-control-color: $text-secondary !default;
$quicklinks-background: $brand-primary-lighter !default;
$sp-loading-color: $brand-primary !default;
$sp-disabled-breadcrumb: $text-tertiary !default;
$sp-avatar-border-color: $border-tertiary !default;
$sp-avatar-text-color: $text-secondary !default;
$sp-focus-border-color: $background-primary !default;
$sp-announcement-title-color: $text-primary !default;
$sp-list-cell-color-selected: $panel-primary-text !default;
$data-table-selected: $brand-primary-dark !default;
$table-heading: $text-primary !default;
$status-table-heading: $text-primary !default;
$attachment-icon-color: $link-color !default;
$sp-file-drop-zone-color: $text-secondary !default;
$checkbox-selection-color: $brand-primary-dark !default;
$sc-label-color: $text-secondary !default;
$sc-field-error-color: $brand-danger !default;
$sc-field-error-label-color: $brand-danger !default;
$sc-field-error-text-color: $panel-primary-text !default;
$sc-sticky-item-header-bg: $background-primary !default;
$sp-sc-accordion-hover: $background-secondary !default;
$sp-sc-category-list-hover-color: $link-color !default;
$sp-sc-category-list-badge-color: $text-tertiary !default;
$category-view-toggle-color: $text-tertiary !default;
$sp-clear-all-color: $link-color !default;
$sp-dropdown-menu-options-color: $link-color !default;
$sp-search-results-highlight-color: #E4EBDF !default;
$sp-faceted-search-interactive-color: $link-color !default;
$search-list-item-focus: $background-tertiary !default;
$accessible-placeholder-gray: $text-tertiary !default;
$color-lightest: $panel-primary-text !default;
$kb-title-color: $link-color !default;
$kb-border: $border-tertiary !default;
$kb-create-comment-bg: $background-primary !default;
$kb-article-view-link-color: $link-color !default;
$kb-article-view-link-color-hover: $link-hover-color !default;
$kb-main-search-color: $panel-primary-text !default;
$icon-link-glyph-color: $panel-primary-text !default;


/* --------------------------------------------------------------------------
 * 2. SCALE VARIABLES
 * Spacing / type / icon scales. Widget stylesheets in this app MUST use
 * these instead of arbitrary pixel values. Nothing below $sp-text-xs (12px).
 * -------------------------------------------------------------------------- */
$sp-space-1: 4px !default;
$sp-space-2: 8px !default;
$sp-space-3: 12px !default;
$sp-space-4: 16px !default;
$sp-space-5: 24px !default;
$sp-space-6: 32px !default;
$sp-space-7: 48px !default;
$sp-space-8: 64px !default;

$sp-text-xs: 12px !default;
$sp-text-sm: 14px !default;
$sp-text-base: 16px !default;
$sp-text-md: 18px !default;
$sp-text-lg: 22px !default;
$sp-text-xl: 26px !default;
$sp-text-2xl: 32px !default;

$sp-icon-xs: 12px !default;
$sp-icon-sm: 16px !default;
$sp-icon-md: 20px !default;
$sp-icon-lg: 32px !default;
$sp-icon-xl: 48px !default;


/* --------------------------------------------------------------------------
 * 3. RUNTIME DESIGN TOKENS — LIGHT  (default) and DARK
 *
 * The Theme Toggle widget flips ONE attribute on <html>:
 *     document.documentElement.setAttribute('data-edp-theme', 'dark')
 * Everything below re-resolves from that single switch.
 *
 * Contrast notes (verified, WCAG 2.x relative-luminance maths):
 *   light: #2A2622 on #FFFCFA = 14.6:1 | #635A52 on #F7F3EF = 6.4:1
 *          #4C6349 on #F7F3EF =  6.0:1 | #FFFCFA on #4C6349 = 6.5:1
 *          #6E8B6B on #FFFCFA =  3.7:1 (non-text accent / borders only)
 *   dark : #F3EDE7 on #1B1816 = 15.3:1 | #C3B8AE on #1B1816 = 9.0:1
 *          #BCD2B4 on #1B1816 = 11.0:1 | #1B1816 on #A8C2A0 = 9.2:1
 * Glass surfaces below are intentionally >=0.72 alpha (tiles/dialogs >=0.88)
 * so text never sits on a layer translucent enough to drop below 4.5:1.
 * -------------------------------------------------------------------------- */
:root,
[data-edp-theme='light'] {
    /* --- sage accent ramp (muted, grey-green — dried sage leaf) --- */
    --edp-sage-50: #F4F7F2;
    --edp-sage-100: #E4EBDF;
    --edp-sage-200: #CBD9C4;
    --edp-sage-300: #AEC2A7;
    --edp-sage-400: #8AA37E;
    --edp-sage-500: #7D9471;
    --edp-sage-600: #6E8B6B;
    --edp-sage-700: #556E52;
    --edp-sage-800: #3A4C38;

    /* --- warm neutral ramp --- */
    --edp-stone-0: #FFFCFA;
    --edp-stone-50: #F7F3EF;
    --edp-stone-100: #EFE9E3;
    --edp-stone-200: #E2DAD2;
    --edp-stone-300: #CFC5BB;
    --edp-stone-400: #A89C91;
    --edp-stone-500: #857A70;
    --edp-stone-600: #635A52;
    --edp-stone-700: #443E39;
    --edp-stone-800: #2A2622;
    --edp-stone-900: #1B1816;

    /* --- semantic surfaces --- */
    --edp-bg: #F7F3EF;
    --edp-bg-elevated: #FFFCFA;
    --edp-surface: rgba(255, 252, 250, 0.82);
    --edp-surface-strong: rgba(255, 252, 250, 0.94);
    --edp-surface-hover: rgba(255, 252, 250, 0.96);
    --edp-surface-sunken: rgba(239, 233, 227, 0.72);
    --edp-hairline: rgba(68, 62, 57, 0.12);
    --edp-hairline-strong: rgba(68, 62, 57, 0.22);
    --edp-scrim: rgba(27, 24, 22, 0.52);

    /* --- frosted glass layer (tiles, carousel, dialogs) ---
       `--edp-glass-surface` stays >=0.88 alpha so body copy on glass keeps
       4.5:1 in both themes even with the heavier blur below. */
    --edp-glass-surface: rgba(255, 252, 250, 0.88);
    --edp-glass-sheen: rgba(255, 255, 255, 0.60);
    --edp-glass-sheen-soft: rgba(255, 255, 255, 0.14);
    --edp-glass-highlight: rgba(255, 255, 255, 0.92);
    --edp-glass-edge: rgba(255, 255, 255, 0.42);
    --edp-glass-shade: rgba(68, 62, 57, 0.06);
    --edp-blur-glass: 30px;
    --edp-glass-saturate: 185%;

    /* --- semantic text --- */
    --edp-text: #2A2622;
    --edp-text-secondary: #443E39;
    --edp-text-muted: #635A52;
    --edp-text-on-accent: #FFFCFA;

    /* --- accent (sage) ---
       `--edp-accent`        : the anchor sage — borders, indicators, dots
       `--edp-accent-strong` : deep sage used behind --edp-text-on-accent so
                               CTA label text clears 4.5:1 (6.5:1 measured)
       `--edp-accent-ink`    : sage text on light surfaces (6.0:1 measured) */
    --edp-accent: #6E8B6B;
    --edp-accent-strong: #4C6349;
    --edp-accent-hover: #556E52;
    --edp-accent-soft: rgba(110, 139, 107, 0.12);
    --edp-accent-soft-hover: rgba(110, 139, 107, 0.20);
    --edp-accent-ink: #4C6349;
    --edp-focus: #556E52;

    /* --- semantic state colours (text-safe on the light surfaces) ---
       Measured on #F7F3EF: danger 5.3:1 | success 5.7:1 | warning 5.8:1 |
       info 5.2:1. The *-soft variants are tinted fills, never text. */
    --edp-danger: #B33A3A;
    --edp-danger-soft: rgba(179, 58, 58, 0.10);
    --edp-success: #2F6B4F;
    --edp-success-soft: rgba(47, 107, 79, 0.10);
    --edp-warning: #7A5A10;
    --edp-warning-soft: rgba(122, 90, 16, 0.10);
    --edp-info: #2F6D8C;
    --edp-info-soft: rgba(47, 109, 140, 0.10);

    /* --- effects --- */
    --edp-blur: 16px;
    --edp-blur-strong: 24px;
    --edp-radius-sm: 8px;
    --edp-radius: 14px;
    --edp-radius-lg: 20px;
    --edp-radius-pill: 999px;
    --edp-shadow-1: 0 1px 2px rgba(68, 62, 57, 0.06), 0 2px 8px rgba(68, 62, 57, 0.06);
    --edp-shadow-2: 0 2px 4px rgba(68, 62, 57, 0.07), 0 10px 24px rgba(68, 62, 57, 0.10);
    --edp-shadow-3: 0 4px 8px rgba(68, 62, 57, 0.09), 0 20px 48px rgba(68, 62, 57, 0.16);
    --edp-aurora-1: rgba(174, 194, 167, 0.60);
    --edp-aurora-2: rgba(203, 217, 196, 0.55);
    --edp-aurora-3: rgba(207, 197, 187, 0.55);
    --edp-aurora-4: rgba(255, 252, 250, 0.70);

    /* --- UXF token remap: keeps sp-rgb() / OOTB widgets on the sage palette
           and makes them flip with the same attribute. Values are the
           "r, g, b" triplets sp-rgb() expects. --- */
    --now-color--primary-0: 228, 235, 223;
    --now-color--primary-1: 110, 139, 107;
    --now-color--primary-2: 76, 99, 73;
    --now-color--primary-3: 58, 76, 56;
    --now-color--interactive-1: 174, 194, 167;
    --now-color--interactive-2: 76, 99, 73;
    --now-color--link-2: 76, 99, 73;
    --now-color--link-3: 58, 76, 56;
    --now-color--focus-ring: 85, 110, 82;
    --now-color--focus-2: 85, 110, 82;
    --now-color_background--primary: 255, 252, 250;
    --now-color_background--secondary: 247, 243, 239;
    --now-color_background--tertiary: 226, 218, 210;
    --now-color_text--primary: 42, 38, 34;
    --now-color_text--secondary: 68, 62, 57;
    --now-color_text--tertiary: 99, 90, 82;
    --now-color_text--primary-actionable: 255, 252, 250;
    --now-color_border--primary: 168, 156, 145;
    --now-color_border--secondary: 207, 197, 187;
    --now-color_border--tertiary: 226, 218, 210;
    --now-color_divider--tertiary: 226, 218, 210;
    --now-form-field--background-color: 255, 252, 250;
}

[data-edp-theme='dark'] {
    --edp-bg: #1B1816;
    --edp-bg-elevated: #2A2622;
    --edp-surface: rgba(42, 38, 34, 0.80);
    --edp-surface-strong: rgba(42, 38, 34, 0.94);
    --edp-surface-hover: rgba(54, 48, 44, 0.94);
    --edp-surface-sunken: rgba(27, 24, 22, 0.76);
    --edp-hairline: rgba(243, 237, 231, 0.12);
    --edp-hairline-strong: rgba(243, 237, 231, 0.24);
    --edp-scrim: rgba(10, 9, 8, 0.66);

    /* Frosted glass layer — dark twin of the light tokens. */
    --edp-glass-surface: rgba(42, 38, 34, 0.88);
    --edp-glass-sheen: rgba(243, 237, 231, 0.10);
    --edp-glass-sheen-soft: rgba(243, 237, 231, 0.04);
    --edp-glass-highlight: rgba(243, 237, 231, 0.26);
    --edp-glass-edge: rgba(243, 237, 231, 0.08);
    --edp-glass-shade: rgba(10, 9, 8, 0.28);
    --edp-blur-glass: 30px;
    --edp-glass-saturate: 165%;

    --edp-text: #F3EDE7;
    --edp-text-secondary: #E2DAD2;
    --edp-text-muted: #C3B8AE;
    --edp-text-on-accent: #1B1816;

    /* Sage lifted for dark surfaces: #A8C2A0 = 9.2:1 on #1B1816,
       #BCD2B4 = 11.0:1, and #1B1816 on #A8C2A0 = 9.2:1. */
    --edp-accent: #A8C2A0;
    --edp-accent-strong: #A8C2A0;
    --edp-accent-hover: #C0D6B8;
    --edp-accent-soft: rgba(168, 194, 160, 0.16);
    --edp-accent-soft-hover: rgba(168, 194, 160, 0.24);
    --edp-accent-ink: #BCD2B4;
    --edp-focus: #BCD2B4;

    /* --- semantic state colours, lifted for dark surfaces ---
       Measured on #1B1816: danger 8.4:1 | success 10.8:1 | warning ~9:1 |
       info ~8.5:1. The *-soft variants are tinted fills, never text. */
    --edp-danger: #E8A1A1;
    --edp-danger-soft: rgba(232, 161, 161, 0.16);
    --edp-success: #A8D5B5;
    --edp-success-soft: rgba(168, 213, 181, 0.16);
    --edp-warning: #E8C77A;
    --edp-warning-soft: rgba(232, 199, 122, 0.16);
    --edp-info: #9DC6DE;
    --edp-info-soft: rgba(157, 198, 222, 0.16);

    --edp-shadow-1: 0 1px 2px rgba(0, 0, 0, 0.32), 0 2px 8px rgba(0, 0, 0, 0.28);
    --edp-shadow-2: 0 2px 4px rgba(0, 0, 0, 0.36), 0 10px 24px rgba(0, 0, 0, 0.40);
    --edp-shadow-3: 0 4px 8px rgba(0, 0, 0, 0.40), 0 20px 48px rgba(0, 0, 0, 0.52);
    --edp-aurora-1: rgba(85, 110, 82, 0.52);
    --edp-aurora-2: rgba(58, 76, 56, 0.60);
    --edp-aurora-3: rgba(68, 62, 57, 0.60);
    --edp-aurora-4: rgba(27, 24, 22, 0.70);

    --now-color--primary-0: 58, 76, 56;
    --now-color--primary-1: 188, 210, 180;
    --now-color--primary-2: 168, 194, 160;
    --now-color--primary-3: 228, 235, 223;
    --now-color--interactive-1: 85, 110, 82;
    --now-color--interactive-2: 188, 210, 180;
    --now-color--link-2: 188, 210, 180;
    --now-color--link-3: 228, 235, 223;
    --now-color--focus-ring: 188, 210, 180;
    --now-color--focus-2: 188, 210, 180;
    --now-color_background--primary: 42, 38, 34;
    --now-color_background--secondary: 27, 24, 22;
    --now-color_background--tertiary: 68, 62, 57;
    --now-color_text--primary: 243, 237, 231;
    --now-color_text--secondary: 226, 218, 210;
    --now-color_text--tertiary: 195, 184, 174;
    --now-color_text--primary-actionable: 27, 24, 22;
    --now-color_border--primary: 133, 122, 112;
    --now-color_border--secondary: 99, 90, 82;
    --now-color_border--tertiary: 68, 62, 57;
    --now-color_divider--tertiary: 68, 62, 57;
    --now-form-field--background-color: 42, 38, 34;
}


/* --------------------------------------------------------------------------
 * 4. GLOBAL SURFACE / FOCUS / MOTION
 * NOTE: deliberately no `body { padding-top }`, no `.navbar-fixed-top` and no
 * bare `nav {}` rules — the Service Portal framework owns header positioning.
 * -------------------------------------------------------------------------- */

/* The portal no longer renders a footer (`SPTheme.footer` is unbound), so the
 * page root has to carry the page background all the way down and fill the
 * viewport. Without this the removed footer leaves a dead strip of the
 * browser's default background under short pages. */
.sp-page-root {
    background-color: var(--edp-bg);
    color: var(--edp-text);
    min-height: 100vh;
}

/* Belt-and-braces: if the framework still emits an empty footer shell for a
 * theme with no footer widget, collapse it so it cannot reserve space. */
.sp-page-root > footer:empty,
body > footer:empty {
    display: none;
}

/* Breathing room where the footer used to be, so the last widget does not sit
 * flush against the viewport edge. */
section.page,
main.body {
    padding-bottom: $sp-space-7;
}

section.page,
main.body {
    background-color: var(--edp-bg);
}

/* Visible focus ring on EVERY interactive element, in both themes. */
a:focus,
button:focus,
input:focus,
select:focus,
textarea:focus,
[tabindex]:focus,
.btn:focus,
.form-control:focus {
    outline: 2px solid var(--edp-focus);
    outline-offset: 2px;
}

/* Where the browser supports it, hide the ring for pointer interaction only. */
.edp-focusable:focus:not(:focus-visible) {
    outline: none;
}

.edp-focusable:focus-visible {
    outline: 2px solid var(--edp-focus);
    outline-offset: 2px;
}

/* Screen-reader-only helper used by the EDP widgets. */
.edp-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Background scroll lock while the Topic Tiles modal is open. */
body.edp-no-scroll {
    overflow: hidden;
}

/* Glassmorphic treatment for every Bootstrap panel in the portal — this is
 * what makes OOTB widgets (My Requests, catalog forms, ...) match the theme. */
.panel {
    background-color: var(--edp-surface);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-1);
    -webkit-backdrop-filter: blur(var(--edp-blur)) saturate(140%);
    backdrop-filter: blur(var(--edp-blur)) saturate(140%);
    color: var(--edp-text);
}

.panel > .panel-heading {
    background-color: transparent;
    border-bottom: 1px solid var(--edp-hairline);
    color: var(--edp-text);
    padding: $sp-space-4 $sp-space-5;
}

.panel .panel-title {
    color: var(--edp-text);
    font-size: $sp-text-md;
    font-weight: 600;
}

.panel > .panel-footer {
    background-color: var(--edp-surface-sunken);
    border-top: 1px solid var(--edp-hairline);
    color: var(--edp-text-secondary);
}

.panel .list-group-item {
    background-color: transparent;
    border-color: var(--edp-hairline);
    color: var(--edp-text);
}

.panel .list-group-item:hover {
    background-color: var(--edp-accent-soft);
}

.text-muted {
    color: var(--edp-text-muted);
}

/* Buttons — the filled button uses --edp-accent-strong so the label keeps
   4.5:1 against the fill in both themes (light 6.5:1 / dark 9.2:1). */
.btn-primary {
    background-color: var(--edp-accent-strong);
    border-color: var(--edp-accent-strong);
    color: var(--edp-text-on-accent);
    border-radius: var(--edp-radius-pill);
    font-weight: 600;
    transition: background-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

.btn-primary:hover,
.btn-primary:focus {
    background-color: var(--edp-accent-hover);
    border-color: var(--edp-accent-hover);
    color: var(--edp-text-on-accent);
    box-shadow: var(--edp-shadow-2);
}

.btn-default {
    background-color: var(--edp-surface-strong);
    border-color: var(--edp-hairline-strong);
    color: var(--edp-accent-ink);
    border-radius: var(--edp-radius-pill);
    font-weight: 600;
}

.btn-default:hover,
.btn-default:focus {
    background-color: var(--edp-surface-hover);
    border-color: var(--edp-accent);
    color: var(--edp-accent-ink);
}

/* Form controls */
.form-control {
    background-color: var(--edp-bg-elevated);
    border: 1px solid var(--edp-hairline-strong);
    border-radius: var(--edp-radius-sm);
    box-shadow: none;
    color: var(--edp-text);
    font-size: $sp-text-base;
}

.form-control:focus {
    border-color: var(--edp-accent);
}

label,
.control-label {
    color: var(--edp-text-secondary);
    font-size: $sp-text-sm;
    font-weight: 600;
}


/* --------------------------------------------------------------------------
 * 5. CATALOG ORDERING EXPERIENCE
 * Themes the OOTB `sc_cat_item` / `sc_category` / `sc_landing` pages so that
 * ordering a catalog item feels like part of this portal.
 * NO SPPage wrapper is created for those OOTB pages — they are styled from
 * here, which is the supported approach.
 * -------------------------------------------------------------------------- */

/* Catalog item form shell — selectors VERIFIED against the live OOTB
 * "SC Catalog Item" widget template (sp_widget 3c29786e87133200e0ef0cf888cb0bdf):
 * the root is `#sc_cat_item`, the title block is `.item-header`, and the
 * sticky title bar is `.sc-sticky-item-header`.
 * (The previously used `.sc-cat-item`, `.cat-item-container`,
 * `.sc-content`, `.sp-form-container` and `.sc-cat-item-content` selectors do
 * NOT exist in that template and have been removed.) */
#sc_cat_item .panel,
#sc_cat_item .item-header,
.sc-sticky-item-header {
    background-color: var(--edp-surface);
    border-radius: var(--edp-radius);
    color: var(--edp-text);
}

.sc-sticky-item-header {
    border-bottom: 1px solid var(--edp-hairline);
    -webkit-backdrop-filter: blur(var(--edp-blur-strong));
    backdrop-filter: blur(var(--edp-blur-strong));
}

/* Variable rows inside the ordering form (`#catalog-form` is the real form id
 * in the OOTB template). */
#sc_cat_item .form-group,
#catalog-form .form-group {
    margin-bottom: $sp-space-4;
}

/* Catalog item cards on the landing page — `.item-card` / `.item-card-column`
 * are VERIFIED against the live OOTB "Recent & Popular Items" widget template
 * (sp_widget 4fc1dd5387500300e0ef0cf888cb0baa). */
.item-card {
    background-color: var(--edp-surface);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-1);
    transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.item-card:hover {
    border-color: var(--edp-accent);
    box-shadow: var(--edp-shadow-2);
    transform: translateY(-2px);
}

/* Order / Submit action area. `#submit-btn`, `.sc-btn` and `.inline-cart` /
 * `.right-side-cart` are VERIFIED against the OOTB SC Catalog Item template. */
#sc_cat_item .btn-primary,
#submit-btn,
.sc-sticky-item-header .btn-primary {
    border-radius: var(--edp-radius-pill);
    padding-left: $sp-space-5;
    padding-right: $sp-space-5;
}

/* Breadcrumbs above the catalog form */
.breadcrumb-container,
.breadcrumbs {
    background-color: transparent;
}

.breadcrumbs .nav-pills > li > a {
    color: var(--edp-accent-ink);
}


/* --------------------------------------------------------------------------
 * 6. REDUCED MOTION
 * Every continuous animation in this portal is defined inside the widgets,
 * but this global guard disables transitions/animations portal-wide for users
 * who ask for reduced motion.
 * -------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
    .panel,
    .btn,
    .btn-primary,
    .btn-default,
    .item-card,
    .group-item,
    .edp-sc-tile {
        transition: none;
    }

    .item-card:hover,
    .group-item:hover,
    .edp-sc-tile:hover {
        transform: none;
    }
}


/* --------------------------------------------------------------------------
 * 7. OOTB BOOTSTRAP + OOTB WIDGET SURFACES  (the dark-mode fix)
 * --------------------------------------------------------------------------
 * ROOT CAUSE of "white things are not visible in dark mode":
 *
 *   `sp_theme.css_variables` is compiled to CSS ONCE, server-side, per theme.
 *   Everything that an OOTB widget stylesheet or the Bootstrap 3 layer
 *   derives from a `$scss-variable` — directly, or through `lighten()` /
 *   `darken()` — is therefore baked into a LITERAL hex at compile time. A
 *   literal hex cannot change when `data-edp-theme` flips on <html>: only
 *   `var(--…)` custom properties re-resolve at runtime.
 *
 *   Concretely, these were frozen at their LIGHT values (verified by reading
 *   the live records):
 *     * `$panel-bg`, `$panel-default-heading-bg`, `$well-bg`,
 *       `$dropdown-bg`, `$modal-content-bg`, `$popover-bg`, `$table-bg-*`,
 *       `$sp-form-field--background-color` … (section 1 of this file)
 *     * `.list-bg-primary { background-color: lighten($panel-info-heading-bg, 6%) }`
 *       in the OOTB "SC Categories" widget (sp_widget 4c03cba0cb11020000f8d856634c9ce1)
 *     * `.sc-sticky-item-header { background-color: $sc-sticky-item-header-bg }`
 *       in the OOTB "SC Catalog Item" widget (sp_widget 3c29786e87133200e0ef0cf888cb0bdf)
 *   and these are hardcoded light literals that NO token touches:
 *     * `.sp-tagline-color { color: #fff !important }` — on the OOTB
 *       `sc_landing` PAGE css (sp_page 53261e3487100300e0ef0cf888cb0b7c)
 *     * `.button-to-top { background-color: #ddd }` — OOTB "SC Scroll to top"
 *       (sp_widget 9cfd91940b4103002600425663673a31)
 *     * `.image-gallery { color: #CECECE }` — OOTB SC Catalog Item
 *
 * FIX: re-declare every surface / text / border colour of the shared
 * Bootstrap layer and of the OOTB widgets in terms of `var(--edp-*)`, so the
 * value is resolved by the browser AFTER the attribute flip. Nothing below
 * uses a compile-time colour. `!important` appears exactly twice, and only
 * where the OOTB rule it has to beat is itself `!important` (noted inline).
 * -------------------------------------------------------------------------- */

/* ---- panels (shell rules live in section 4) ---- */
.panel-body {
    background-color: transparent;
    color: var(--edp-text);
}

.panel-default,
.panel-primary,
.panel-info,
.panel-success,
.panel-warning,
.panel-danger {
    background-color: var(--edp-surface);
    border-color: var(--edp-hairline);
    color: var(--edp-text);
}

.panel-default > .panel-heading,
.panel-primary > .panel-heading,
.panel-info > .panel-heading,
.panel-success > .panel-heading,
.panel-warning > .panel-heading,
.panel-danger > .panel-heading {
    background-color: var(--edp-surface-sunken);
    border-color: var(--edp-hairline);
    color: var(--edp-text);
}

.panel-heading h2,
.panel-heading h3,
.panel-heading h4,
.panel-heading .panel-title,
.panel-heading .panel-title > a {
    color: var(--edp-text);
}

.panel > .list-group,
.panel > .panel-collapse > .list-group {
    background-color: transparent;
}

/* ---- wells ---- */
.well,
.well-sm,
.well-lg {
    background-color: var(--edp-surface-sunken);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: none;
    color: var(--edp-text);
}

/* ---- list groups ---- */
.list-group {
    background-color: transparent;
}

.list-group-item {
    background-color: var(--edp-surface);
    border-color: var(--edp-hairline);
    color: var(--edp-text);
}

a.list-group-item,
button.list-group-item {
    color: var(--edp-text);
}

a.list-group-item:hover,
a.list-group-item:focus,
button.list-group-item:hover,
button.list-group-item:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-text);
}

.list-group-item.active,
.list-group-item.active:hover,
.list-group-item.active:focus {
    background-color: var(--edp-accent-strong);
    border-color: var(--edp-accent-strong);
    color: var(--edp-text-on-accent);
}

.list-group-item-heading {
    color: var(--edp-text);
}

.list-group-item-text {
    color: var(--edp-text-secondary);
}

/* ---- dropdown menus ---- */
.dropdown-menu {
    background-color: var(--edp-surface-strong);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-2);
}

.dropdown-menu > li > a {
    color: var(--edp-text);
}

.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
}

.dropdown-menu > .active > a,
.dropdown-menu > .active > a:hover,
.dropdown-menu > .active > a:focus {
    background-color: var(--edp-accent-strong);
    color: var(--edp-text-on-accent);
}

.dropdown-menu .divider {
    background-color: var(--edp-hairline);
}

.dropdown-header {
    color: var(--edp-text-muted);
}

/* ---- modals ---- */
.modal-content {
    background-color: var(--edp-bg-elevated);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius-lg);
    box-shadow: var(--edp-shadow-3);
    color: var(--edp-text);
}

.modal-header,
.modal-footer {
    border-color: var(--edp-hairline);
}

.modal-title,
.modal-body {
    color: var(--edp-text);
}

.modal-backdrop,
.modal-backdrop.in {
    background-color: var(--edp-scrim);
    opacity: 1;
}

.close {
    color: var(--edp-text);
    opacity: 0.75;
    text-shadow: none;
}

.close:hover,
.close:focus {
    color: var(--edp-text);
    opacity: 1;
}

/* ---- popovers ---- */
.popover {
    background-color: var(--edp-surface-strong);
    border-color: var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-2);
    color: var(--edp-text);
}

.popover-title {
    background-color: var(--edp-surface-sunken);
    border-color: var(--edp-hairline);
    color: var(--edp-text);
}

.popover-content {
    color: var(--edp-text);
}

.popover.top > .arrow:after {
    border-top-color: var(--edp-surface-strong);
}

.popover.bottom > .arrow:after {
    border-bottom-color: var(--edp-surface-strong);
}

.popover.left > .arrow:after {
    border-left-color: var(--edp-surface-strong);
}

.popover.right > .arrow:after {
    border-right-color: var(--edp-surface-strong);
}

/* ---- tooltips (inverted on purpose, in both themes) ---- */
.tooltip,
.tooltip.in {
    opacity: 1;
}

.tooltip-inner {
    background-color: var(--edp-text);
    color: var(--edp-bg-elevated);
    border-radius: var(--edp-radius-sm);
    font-size: $sp-text-xs;
}

.tooltip.top .tooltip-arrow {
    border-top-color: var(--edp-text);
}

.tooltip.bottom .tooltip-arrow {
    border-bottom-color: var(--edp-text);
}

.tooltip.left .tooltip-arrow {
    border-left-color: var(--edp-text);
}

.tooltip.right .tooltip-arrow {
    border-right-color: var(--edp-text);
}

/* ---- tables ---- */
.table {
    background-color: transparent;
    color: var(--edp-text);
}

.table > thead > tr > th {
    background-color: var(--edp-surface-sunken);
    border-bottom-color: var(--edp-hairline-strong);
    color: var(--edp-text);
}

.table > tbody > tr > td,
.table > tbody > tr > th,
.table > tfoot > tr > td,
.table > tfoot > tr > th {
    border-top-color: var(--edp-hairline);
    color: var(--edp-text);
}

.table > tbody > tr {
    background-color: transparent;
}

.table-striped > tbody > tr:nth-of-type(odd) {
    background-color: var(--edp-surface-sunken);
}

.table-hover > tbody > tr:hover {
    background-color: var(--edp-accent-soft);
}

.table-bordered,
.table-bordered > thead > tr > th,
.table-bordered > tbody > tr > td,
.table-bordered > tbody > tr > th {
    border-color: var(--edp-hairline);
}

.table caption {
    color: var(--edp-text-secondary);
}

/* ---- form controls, selects, textareas ---- */
select.form-control,
textarea.form-control,
input[type='text'],
input[type='search'],
input[type='email'],
input[type='url'],
input[type='tel'],
input[type='number'],
input[type='password'],
input[type='date'],
input[type='datetime-local'],
select,
textarea {
    background-color: var(--edp-bg-elevated);
    border: 1px solid var(--edp-hairline-strong);
    border-radius: var(--edp-radius-sm);
    color: var(--edp-text);
}

.form-control[disabled],
.form-control[readonly],
fieldset[disabled] .form-control {
    background-color: var(--edp-surface-sunken);
    color: var(--edp-text-muted);
}

.input-group-addon {
    background-color: var(--edp-surface-sunken);
    border-color: var(--edp-hairline-strong);
    color: var(--edp-text-secondary);
}

/* Placeholder text — one rule per vendor prefix on purpose: grouping them
   makes the whole declaration invalid in several engines. */
.form-control::placeholder,
input::placeholder,
textarea::placeholder {
    color: var(--edp-text-muted);
    opacity: 1;
}

.form-control::-webkit-input-placeholder {
    color: var(--edp-text-muted);
    opacity: 1;
}

.form-control::-moz-placeholder {
    color: var(--edp-text-muted);
    opacity: 1;
}

.form-control:-ms-input-placeholder {
    color: var(--edp-text-muted);
    opacity: 1;
}

.help-block,
.form-text {
    color: var(--edp-text-muted);
}

.has-error .form-control {
    border-color: var(--edp-danger);
}

.has-error .control-label,
.has-error .help-block {
    color: var(--edp-danger);
}

/* Select2 is what the OOTB catalog widgets actually render for <select>
   (verified: `.select2-choice` / `.select2-results` / `.select2-focusser`
   appear in the SC Catalog Item and SC Categories sources). */
.select2-container .select2-choice,
.select2-container .select2-choice > .select2-chosen,
.select2-drop,
.select2-drop-active,
.select2-results {
    background-color: var(--edp-bg-elevated);
    border-color: var(--edp-hairline-strong);
    color: var(--edp-text);
}

.select2-results .select2-highlighted {
    background-color: var(--edp-accent-soft);
    color: var(--edp-text);
}

/* ---- breadcrumbs (verified: OOTB `breadcrumbs` widget
       sp_widget 0fb269305b3212000d7ec7ad31f91ae2) ---- */
.breadcrumb {
    background-color: transparent;
}

nav.breadcrumbs .nav-pills > li > a {
    color: var(--edp-accent-ink);
}

nav.breadcrumbs .nav-pills > li > a:hover,
nav.breadcrumbs .nav-pills > li > a:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
}

nav.breadcrumbs .a-disabled,
.breadcrumb > .active {
    color: var(--edp-text-muted);
}

nav.breadcrumbs .fa-chevron-right,
.breadcrumb > li + li:before {
    color: var(--edp-text-muted);
}

/* ---- badges, labels, pagination ---- */
.badge,
.panel-primary .badge,
.panel-default .badge,
.category-list .badge {
    background-color: var(--edp-accent-strong);
    color: var(--edp-text-on-accent);
}

.label-default {
    background-color: var(--edp-surface-sunken);
    color: var(--edp-text);
}

.pagination > li > a,
.pagination > li > span {
    background-color: var(--edp-surface);
    border-color: var(--edp-hairline);
    color: var(--edp-accent-ink);
}

.pagination > li > a:hover,
.pagination > li > a:focus {
    background-color: var(--edp-accent-soft);
    border-color: var(--edp-accent);
    color: var(--edp-accent-ink);
}

.pagination > .active > a,
.pagination > .active > span,
.pagination > .active > a:hover,
.pagination > .active > span:hover {
    background-color: var(--edp-accent-strong);
    border-color: var(--edp-accent-strong);
    color: var(--edp-text-on-accent);
}

.pagination > .disabled > span,
.pagination > .disabled > a {
    background-color: var(--edp-surface-sunken);
    border-color: var(--edp-hairline);
    color: var(--edp-text-muted);
}

/* ---- tabs / nav ---- */
.nav-tabs {
    border-bottom-color: var(--edp-hairline);
}

.nav-tabs > li > a {
    color: var(--edp-text-secondary);
}

.nav > li > a:hover,
.nav > li > a:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
}

.nav-tabs > li.active > a,
.nav-tabs > li.active > a:hover,
.nav-tabs > li.active > a:focus {
    background-color: var(--edp-surface);
    border-color: var(--edp-hairline);
    border-bottom-color: transparent;
    color: var(--edp-accent-ink);
}

/* ---- alerts ---- */
.alert {
    border-radius: var(--edp-radius);
    border-width: 1px;
    color: var(--edp-text);
}

.alert-info,
.alert-suggestion {
    background-color: var(--edp-info-soft);
    border-color: var(--edp-info);
}

.alert-success {
    background-color: var(--edp-success-soft);
    border-color: var(--edp-success);
}

.alert-warning {
    background-color: var(--edp-warning-soft);
    border-color: var(--edp-warning);
}

.alert-danger {
    background-color: var(--edp-danger-soft);
    border-color: var(--edp-danger);
}

.alert a,
.alert .alert-link {
    color: var(--edp-accent-ink);
}

/* ---- shared text / link helpers ---- */
.text-muted,
small.text-muted {
    color: var(--edp-text-muted);
}

.text-primary,
.btn-link {
    color: var(--edp-accent-ink);
}

.btn-link:hover,
.btn-link:focus {
    color: var(--edp-accent-hover);
}

hr {
    border-top-color: var(--edp-hairline);
}

code,
pre {
    background-color: var(--edp-surface-sunken);
    border-color: var(--edp-hairline);
    color: var(--edp-text);
}

/* ---- OOTB widget shells shared by My Requests / Requests & Approvals /
       Recent & Popular Items / Saved Bundles (verified: `.panels-container`,
       `.no-data-message`, `.bundles-container`, `.sc-tab-div`,
       `div.request`, `div.approval`, `div.recent`, `div.popular`) ---- */
.panels-container,
.bundles-container {
    background-color: transparent;
    color: var(--edp-text);
}

.no-data-message {
    color: var(--edp-text-muted);
}

div.request,
div.approval,
div.recent,
div.popular {
    color: var(--edp-text-secondary);
}

div.request.sc-tab-div,
div.approval.sc-tab-div,
div.recent.sc-tab-div,
div.popular.sc-tab-div {
    border-bottom-color: var(--edp-accent);
    color: var(--edp-accent-ink);
}

/* ---- hardcoded light literals in OOTB CSS that no token can reach ---- */
/* OOTB "SC Scroll to top" paints `#ddd` and marks opacity/border !important,
   so the override has to be !important too. */
.button-to-top {
    background-color: var(--edp-surface-strong) !important;
    border-color: var(--edp-hairline-strong) !important;
    color: var(--edp-accent-ink);
    opacity: 1 !important;
}

.image-gallery {
    color: var(--edp-hairline-strong);
}

.image-gallery .active {
    color: var(--edp-accent);
}


/* --------------------------------------------------------------------------
 * 8. CATALOG JOURNEY  —  sc_landing / sc_category / sc_cat_item / search
 * --------------------------------------------------------------------------
 * Styled from the THEME only: no SPPage wrapper is created for any OOTB page.
 *
 * SELECTOR PROVENANCE
 *   VERIFIED against live records (read with run_query before writing a rule):
 *     sp_page  53261e3487100300e0ef0cf888cb0b7c  (sc_landing + its page CSS)
 *     sp_widget e709a97287580300e0ef0cf888cb0bdd  Catalog Homepage Search
 *     sp_widget 4fc1dd5387500300e0ef0cf888cb0baa  Recent & Popular Items
 *     sp_widget 55ccec906701220023c82e08f585ef82  SC Saved Carts
 *     sp_widget 69deca02675003004b8d794717415a9b  Requests and Approvals
 *     sp_widget abc50de6d702120023c84f80de61036a  link-button
 *     sp_widget 9cfd91940b4103002600425663673a31  SC Scroll to top
 *     sp_widget 4c03cba0cb11020000f8d856634c9ce1  SC Categories
 *     sp_widget 0fb269305b3212000d7ec7ad31f91ae2  breadcrumbs
 *     sp_widget 3c29786e87133200e0ef0cf888cb0bdf  SC Catalog Item
 *   BEST EFFORT (NOT verified against a template — see the report):
 *     the typeahead / AI-search result list selectors at the end of this
 *     section.
 * -------------------------------------------------------------------------- */

/* ---- sc_landing: the hero search block ---------------------------------- */
/* `#homepage-search`, `.search-bar` and `.sp-tagline-color` are verified. */
#homepage-search {
    padding: $sp-space-7 $sp-space-5;
    margin-bottom: $sp-space-6;
    border-radius: var(--edp-radius-lg);
    border: 1px solid var(--edp-hairline);
    background-color: var(--edp-glass-surface);
    box-shadow: var(--edp-shadow-2);
    -webkit-backdrop-filter: blur(var(--edp-blur-strong)) saturate(150%);
    backdrop-filter: blur(var(--edp-blur-strong)) saturate(150%);
}

/* The sc_landing PAGE css hardcodes `.sp-tagline-color { color: #fff
   !important }`, which is invisible on this portal's warm light surface and
   is the single biggest reason the page "looks bad". Page CSS wins over theme
   CSS by load order AND carries !important, so this override needs both extra
   specificity (`body …`) and !important. This is the only other !important in
   this file. */
body #homepage-search .sp-tagline-color,
body #homepage-search a.sp-tagline-color {
    color: var(--edp-text) !important;
}

#homepage-search h2.sp-tagline-color {
    font-size: $sp-text-2xl;
    font-weight: 700;
    letter-spacing: -0.015em;
}

#homepage-search .h4.sp-tagline-color {
    color: var(--edp-text-secondary) !important;
    font-size: $sp-text-md;
}

#homepage-search a.sp-tagline-color {
    color: var(--edp-accent-ink) !important;
    font-size: $sp-text-base;
}

/* OOTB fixes `.search-bar` at 600px, which overflows small viewports. */
#homepage-search .search-bar {
    width: 100%;
    max-width: 600px;
    margin: 0 auto;
}

#homepage-search .search-bar .form-control {
    height: 44px;
    border-radius: var(--edp-radius-pill);
    background-color: var(--edp-bg-elevated);
    border-color: var(--edp-hairline-strong);
    font-size: $sp-text-base;
}

/* ---- sc_landing: link-button + recent/popular + saved bundles ---------- */
.recent-widget .panel,
.bundles-container {
    border-radius: var(--edp-radius);
}

.bundle-title {
    border-bottom: 1px solid var(--edp-hairline);
}

.bundle-title-content {
    color: var(--edp-text);
    font-size: $sp-text-md;
    font-weight: 600;
}

.item-card-column {
    display: flex;
    flex-direction: column;
}

.item-card .panel-body {
    padding: $sp-space-4;
}

.catalog-item-name {
    color: var(--edp-accent-ink);
    font-size: $sp-text-md;
    font-weight: 600;
    text-decoration: none;
}

.item-card:hover .catalog-item-name {
    text-decoration: underline;
}

.item-short-desc {
    color: var(--edp-text-muted);
    font-size: $sp-text-sm;
    line-height: 1.5;
}

.item-card + .panel-footer,
.panel-footer.b {
    background-color: var(--edp-surface-sunken);
    border-top: 1px solid var(--edp-hairline);
    border-bottom-left-radius: var(--edp-radius);
    border-bottom-right-radius: var(--edp-radius);
    color: var(--edp-text-secondary);
    font-size: $sp-text-sm;
}

.item-price {
    color: var(--edp-text);
    font-size: $sp-text-sm;
}

.item-image {
    border-radius: var(--edp-radius-sm);
    background-color: var(--edp-surface-strong);
}

/* ---- sc_category: the category tree ------------------------------------ */
.category-widget {
    background-color: var(--edp-surface);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-1);
}

.category-widget .panel-heading,
.category-widget .panel-primary.panel-heading {
    background-color: transparent;
    border-bottom: 1px solid var(--edp-hairline);
    color: var(--edp-text);
}

.category-list,
.sub-category-list {
    background-color: transparent;
}

.category-list .list-group-item {
    background-color: transparent;
    border: 0;
}

.group-item {
    border-radius: var(--edp-radius-sm);
    color: var(--edp-text);
    transition: background-color 160ms ease, border-color 160ms ease;
}

.group-item-primary:hover,
.group-item-primary:focus {
    background-color: var(--edp-accent-soft);
}

.list-bg-primary,
.list-bg-default,
.list-bg-info,
.list-bg-success,
.list-bg-warning,
.list-bg-danger {
    background-color: var(--edp-surface-sunken);
}

.text-active {
    color: var(--edp-accent-ink);
    border-left-color: var(--edp-accent);
}

.collapse-icon {
    color: var(--edp-text-muted);
}

.sc-basic-select,
.sn-select-basic {
    background-color: var(--edp-bg-elevated);
    border: 1px solid var(--edp-hairline-strong);
    border-radius: var(--edp-radius-sm);
    color: var(--edp-text);
    font-size: $sp-text-sm;
}

#show-more-btn {
    color: var(--edp-accent-ink);
    font-size: $sp-text-sm;
    font-weight: 600;
}

/* ---- sc_cat_item: the ordering form ------------------------------------ */
#sc_cat_item .panel {
    border: 1px solid var(--edp-hairline);
    box-shadow: var(--edp-shadow-1);
}

#sc_cat_item .item-header,
.sc-sticky-item-header {
    border-bottom: 1px solid var(--edp-hairline);
    -webkit-backdrop-filter: blur(var(--edp-blur-strong));
    backdrop-filter: blur(var(--edp-blur-strong));
}

#sc_cat_item .item-header h2 {
    color: var(--edp-text);
    font-size: $sp-text-xl;
    font-weight: 700;
    letter-spacing: -0.01em;
}

.sc-cat-item-short-description {
    color: var(--edp-text-muted);
    font-size: $sp-text-base;
}

.sc-item-description {
    color: var(--edp-text-secondary);
    font-size: $sp-text-base;
    line-height: 1.6;
}

.sc-cat-item-legend {
    color: var(--edp-text-muted);
    font-size: $sp-text-sm;
}

.mandatory,
.sc-field-error-color {
    color: var(--edp-danger);
}

.catalog-item-image {
    border-radius: var(--edp-radius);
    background-color: var(--edp-surface-strong);
}

.drag-and-drop-area {
    background-color: var(--edp-surface-sunken);
    border: 1px dashed var(--edp-hairline-strong);
    border-radius: var(--edp-radius);
    color: var(--edp-text-secondary);
}

.cat-item-quantity-label,
#sc_cat_item label,
#sc_cat_item .control-label {
    color: var(--edp-text-secondary);
}

.sc-btn {
    border-radius: var(--edp-radius-pill);
    color: var(--edp-accent-ink);
}

.sc-field-error-label,
.sc-reqd-info-btn {
    background-color: var(--edp-danger-soft);
    border: 1px solid var(--edp-danger);
    border-radius: var(--edp-radius-pill);
    color: var(--edp-text);
    font-size: $sp-text-xs;
    font-weight: 600;
}

.right-side-cart .panel,
.inline-cart {
    border-radius: var(--edp-radius);
}

/* ---- search / typeahead results ---------------------------------------
 * BEST EFFORT: these class names were NOT verified against the
 * `typeahead-search` template (that record was not read), so they are written
 * defensively — each rule only sets colour/radius, so a miss is a no-op and
 * cannot break the OOTB layout.
 * -------------------------------------------------------------------- */
.typeahead,
.tt-menu,
.tt-dropdown-menu,
.sp-search-results,
.search-results {
    background-color: var(--edp-surface-strong);
    border: 1px solid var(--edp-hairline);
    border-radius: var(--edp-radius);
    box-shadow: var(--edp-shadow-2);
    color: var(--edp-text);
}

.tt-suggestion,
.sp-search-result,
.search-result-item {
    color: var(--edp-text);
}

.tt-suggestion:hover,
.tt-suggestion.tt-cursor,
.sp-search-result:hover,
.search-result-item:hover {
    background-color: var(--edp-accent-soft);
    color: var(--edp-text);
}

.search-list-item:focus {
    background-color: var(--edp-accent-soft);
}


/* --------------------------------------------------------------------------
 * 9. EXPLICIT DARK-SCOPE HARDENING
 * --------------------------------------------------------------------------
 * Everything above already flips, because it resolves `var(--edp-*)` at
 * runtime. This block exists for the handful of OOTB surfaces whose light
 * appearance comes from somewhere a generic token rule cannot reach (a
 * compile-time `lighten()`, a page-level `!important`, or an <img> that needs
 * a backing plate on a dark page). Keeping them here, scoped to
 * `[data-edp-theme='dark']`, makes the dark-only intent explicit.
 * -------------------------------------------------------------------------- */
[data-edp-theme='dark'] {
    /* compile-time `lighten($panel-info-heading-bg, 6%)` in SC Categories */
    .list-bg-primary,
    .list-bg-default,
    .list-bg-info,
    .list-bg-success,
    .list-bg-warning,
    .list-bg-danger {
        background-color: var(--edp-surface-sunken);
    }

    /* compile-time `$sc-sticky-item-header-bg` in SC Catalog Item */
    .sc-sticky-item-header,
    #sc_cat_item .item-header {
        background-color: var(--edp-bg-elevated);
    }

    /* `#fff !important` on the sc_landing page record */
    body #homepage-search .sp-tagline-color,
    body #homepage-search a.sp-tagline-color {
        color: var(--edp-text) !important;
    }

    /* `#ddd` in SC Scroll to top */
    .button-to-top {
        background-color: var(--edp-surface-strong) !important;
        color: var(--edp-accent-ink);
    }

    /* Catalog artwork is authored for light pages: give it a plate so a
       transparent PNG never becomes an invisible smudge. */
    .catalog-item-image,
    .item-image {
        background-color: var(--edp-surface-strong);
    }

    /* OOTB table headers inherit a frozen light tint in places. */
    .table > thead > tr > th {
        background-color: var(--edp-surface-sunken);
        color: var(--edp-text);
    }
}


/* --------------------------------------------------------------------------
 * 10. REDUCED MOTION — guard for the transitions added in sections 7-8
 * -------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
    .group-item,
    .list-group-item,
    .pagination > li > a,
    .sc-btn {
        transition: none;
    }
}


/* --------------------------------------------------------------------------
 * 11. OOTB "My Requests" (`my-requests-v2`) + page-link safety net
 * --------------------------------------------------------------------------
 * Selectors VERIFIED against the live record (sp_widget
 * 8cc0df25875023000f220cf888cb0bb5). Three things in that widget's own CSS
 * are compile-time frozen and were unreadable in dark mode:
 *   * `.uib-vis-tab > a { color: $sp-nav-tabs-color }`      (tab labels)
 *   * `.nav-tabs > li.active > a { color: $sp-nav-tabs-active-tab }`
 *   * `.column-headers { position: sticky }` with NO background, so the
 *     scrolling rows showed through the header row
 * -------------------------------------------------------------------------- */
.uib-vis-tab > a {
    color: var(--edp-text-secondary);
}

.uib-vis-tab.active > a,
.nav-tabs > li.active > a {
    color: var(--edp-accent-ink);
}

.column-headers {
    background-color: var(--edp-surface-strong);
    color: var(--edp-text);
}

.column-headers .list-group-item {
    background-color: transparent;
    border-color: var(--edp-hairline);
}

.requests-header-container {
    background-color: transparent;
}

.primary-display a {
    color: var(--edp-accent-ink);
    font-weight: 600;
}

.secondary-display,
.state,
.updated {
    color: var(--edp-text-muted);
    font-size: $sp-text-sm;
}

.draft-item-row,
.draft-item-cell {
    color: var(--edp-text);
}

.btn-show-more {
    border-radius: var(--edp-radius-pill);
}

.btn-clear,
.btn-remove {
    background-color: transparent;
    color: var(--edp-text-secondary);
}

.btn-clear:hover .btn-remove,
.btn-clear:focus .btn-remove {
    color: var(--edp-danger);
}

.panel-align {
    color: var(--edp-text-muted);
}

/* Safety net for every OOTB page link: `$link-color` is a compile-time SCSS
 * variable, so if it collapses to a literal the link colour cannot flip. This
 * re-asserts it from a runtime token for body content only — the header/footer
 * set their own link colours, and `.btn`s are excluded so button labels keep
 * their on-accent colour. */
main.body a:not(.btn),
section.page a:not(.btn) {
    color: var(--edp-accent-ink);
}

main.body a:not(.btn):hover,
main.body a:not(.btn):focus,
section.page a:not(.btn):hover,
section.page a:not(.btn):focus {
    color: var(--edp-accent-hover);
}
